async function piBookingLaunchBrowser(pw) {
  piBookingEnsureDisplay();
  const args = ['--disable-blink-features=AutomationControlled', '--disable-dev-shm-usage', '--no-sandbox', '--disable-setuid-sandbox', '--disable-infobars', '--disable-gpu', '--disable-software-rasterizer', '--window-size=1440,900'];
  const proxy = process.env.PLAYWRIGHT_PROXY_SERVER || process.env.HTTPS_PROXY || process.env.HTTP_PROXY || '';
  const opts = { headless: false, args: args, ignoreDefaultArgs: ['--enable-automation'] };
  if (proxy) opts.proxy = { server: proxy };
  let lastErr = null;
  for (let attempt = 0; attempt < 2; attempt++) {
    if (attempt) {
      try { delete process.env.DISPLAY; } catch (eUnset) {}
      piBookingEnsureDisplay();
    }
    try {
      return await pw.chromium.launch(Object.assign({}, opts, { channel: 'chrome' }));
    } catch (eChrome) {
      lastErr = eChrome;
      try {
        return await pw.chromium.launch(opts);
      } catch (eHeaded) {
        lastErr = eHeaded;
      }
    }
  }
  throw new Error('Booking.com Connect needs headed Chrome (Xvfb). ' + String((lastErr && lastErr.message) || lastErr || 'launch failed'));
}

